package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamTheoryColorBank2 {
    private const val T = "චිත්‍ර කලා මූලිකාංග, නිර්මාණ මූලධර්ම හා වර්ණ න්‍යාය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("චිත්‍ර කලාවේ 'තාන පරිමාණය' (Value Scale / Grey Scale) ගොඩනැගෙන්නේ කුමන අන්ත දෙක අතරද?", "පිරිසිදු සුදු සිට තද කළු දක්වා", "රතු පැහැයේ සිට කොළ දක්වා", "නිල් පැහැයේ සිට තැඹිලි දක්වා", "කහ පැහැයේ සිට දම් දක්වා", "සෙවණැලි හා ආලෝකය නිවැරදිව පාලනය කිරීමට පියවර 5 සිට 9 දක්වා අඳුරු-එළි පරිමාණ පුහුණු කෙරේ."),
        q("වස්තුවක් මත ආලෝකය වැටී ඇති විට 'පරාවර්තන ආලෝකය' (Reflected Light) යනු කුමක්ද?", "අසල පෘෂ්ඨයෙන් අඳුරු දාරයට වැටෙන එළිය", "ප්‍රභවයෙන් මුදුනට කෙළින් වැටෙන එළිය", "බිම මත වස්තුවෙන් ඇතිවන තද සෙවණැල්ල", "වස්තුවේ ඉදිරිපස ඇති දිලිසෙන ආලෝක ලපය", "ගෝලයක අඳුරුම හරයට (Core Shadow) පහළින් මේසයෙන් පරාවර්තනය වන මෘදු ආලෝකය ත්‍රිමාණ බව වැඩි කරයි."),
        q("ගෝලාකාර වස්තුවක 'හර සෙවණැල්ල' (Core Shadow) පිහිටන්නේ කුමන ස්ථානයේද?", "ආලෝකය හා පරාවර්තන එළිය අතර අඳුරු තීරුවේ", "බිම මත ඈතින්ම පිහිටි වැටෙන සෙවණැලි කෙළවරේ", "ආලෝක ප්‍රභවයට කෙළින්ම මුහුණලා ඇති තැනේ", "වස්තුවේ ඉහළම පෘෂ්ඨයේ ඇති උච්ච ආලෝක ලපයේ", "හර සෙවණැල්ල හා පරාවර්තන ආලෝකය නිවැරදිව ඇඳීමෙන් සිතුවමට යථාර්ථවාදී බරක් ලැබේ."),
        q("විශේෂිත තාන ක්‍රමයක් වන 'ස්මජිං හෙවත් ස්ටම්පිං' (Smudging / Blending) යනු කුමක්ද?", "පැන්සල් රේඛා කඩදාසි කූරකින් මෘදුව මුසු කිරීම", "සියුම් තිත් පමණක් තබා අඳුරු තාන මැවීම", "සමාන්තර හරස් රේඛා ජාලයක් ලෙස ඇඳීම", "වියළි පින්සලෙන් රළු තීන්ත පහරවල් තැවරීම", "ඉතා සිනිඳු සම, වීදුරු හෝ ලෝහ පෘෂ්ඨවල සෙවණැලි මාරුවීම් දැක්වීමට මුසු කිරීම යොදා ගනී."),
        q("රේඛාවේ ස්වභාවය අනුව 'වක්‍රාකාර සර්පිලාකාර රේඛා' (Spiral Lines) මගින් දැනවෙන හැඟීම කුමක්ද?", "ක්‍රමික වර්ධනය, ගමනාන්තය හා රිද්මය", "දැඩි නිශ්චල බව හා ස්ථාවර සමබරතාව", "තියුණු කැපීම, ගැටුම හා ක්ෂණික වේගය", "පැතලි සමාන්තර බව හා නිහඬ නිද්‍රාශීලී බව", "හම්බෙලි කටුවක හෝ ලියවැලක මෙන් සර්පිලාකාර රේඛා ක්‍රමානුකූල වර්ධනය හා ලාලිත්‍යය පෙන්වයි."),
        q("කැඩුණු හෝ කඩඉරි (Broken / Dashed Lines) චිත්‍රයක භාවිත කිරීමෙන් ප්‍රකාශ කළ හැකි ගුණාංගය කුමක්ද?", "අවිනිශ්චිත බව, සැහැල්ලු බව හෝ චලනය", "දැඩි ශිලාමය බර හා නොසැලෙන ස්ථාවරත්වය", "අඛණ්ඩ සමමිතික බව හා දැඩි විනය", "ඝන සංවෘත බව හා අඳුරු නිශ්චලතාව", "රේඛාවේ ඝනකම, තද බව හා අඛණ්ඩතාව වෙනස් කිරීමෙන් විවිධ මානසික ප්‍රකාශන ලබා ගත හැකිය."),
        q("චිත්‍රයක 'අභිනය රේඛා' (Gesture Drawing) පුහුණුවීමෙන් කලා සිසුවෙකුට ලැබෙන ප්‍රධාන ප්‍රයෝජනය කුමක්ද?", "සිරුරක මූලික චලනය හා ඉරියව්ව ඉක්මනින් ඇඳීම", "වර්ණ චක්‍රයේ උණුසුම් හා සිසිල් වර්ණ වෙන් කිරීම", "දීර්ඝ කාලයක් ගෙන සියුම් වයනය පිටපත් කිරීම", "රේඛීය දෘෂ්ටිකෝණයේ අභිසාරී ලක්ෂ්‍ය සෙවීම", "තත්පර 30 සිට මිනිත්තු 2 දක්වා කාලයකදී ඉක්මන් චලන රේඛා ඇඳීම අත හා ඇස හුරු කරවයි."),
        q("වස්තුව දෙස පමණක් බලාගෙන කඩදාසිය දෙස නොබලා අඛණ්ඩව රේඛාව ඇඳීමේ පුහුණු අභ්‍යාසය කුමක්ද?", "අන්ධ සමෝච්ඡ රේඛා ඇඳීම (Blind Contour)", "හරස් ඉරි තාන ඇඳීම (Cross-Hatching)", "ලක්ෂ්‍යමය තිත් ඇඳීම (Pointillism)", "පසුබිම් මුද්‍රණ ක්‍රමය (Block Printing)", "ඇස සහ අත අතර සම්බන්ධතාව ශක්තිමත් කිරීමට හා සූක්ෂ්ම නිරීක්ෂණයට අන්ධ සමෝච්ඡ ක්‍රමය යොදයි."),
        q("වර්ණ මනෝවිද්‍යාව (Color Psychology) අනුව 'කොළ' වර්ණයෙන් ප්‍රධාන වශයෙන් සංකේතවත් කරන්නේ මොනවාද?", "සොබාදහම, සෞඛ්‍යය, නැවුම් බව, වර්ධනය සහ සාමය", "ගින්න, කෝපය සහ යුද්ධය", "අධික ශෝකය හා අඳුර", "ශීත හිම කුණාටුව", "ශාක පත්‍ර හා පරිසරය සිහිගන්වන කොළ වර්ණය ඇසට විවේකයක් හා සුවදායක බවක් ගෙන දෙයි."),
        q("පෝස්ටර් හා වෙළඳ නිර්මාණවල 'රතු' වර්ණය අනතුරු ඇඟවීමට හා ආහාර දැන්වීම්වලට බහුලව යොදා ගන්නේ ඇයි?", "ඇස වේගයෙන් ආකර්ෂණය කර උද්යෝගය වඩවන බැවින්", "එය ඉතාම සිසිල් හා නිහඬ පැහැයක් වන බැවින්", "අඳුරු පසුබිමේ සම්පූර්ණයෙන් නොපෙනෙන බැවින්", "සියලු වර්ණ අතරින් අඩුම දීප්තියක් දෙන බැවින්", "දිගු තරංග ආයාමයක් ඇති රතු වර්ණය ඕනෑම පසුබිමක ඉක්මනින් අවධානය දිනා ගනී."),
        q("වර්ණ චක්‍රයේ 'නිල්' වර්ණය මිනිස් මනසට බලපාන ආකාරය කුමක්ද?", "සන්සුන් බව, විශ්වාසය, ගැඹුර හා සිසිල් බව", "අධික උණුසුම, කෝපය හා ආක්‍රමණශීලී බව", "වේගවත් කුසගින්න හා කලබලකාරී හැඟීම", "දීප්තිමත් ගිනි රශ්මිය හා හදිසි අනතුර", "නිල් වර්ණය ආයතනික ලාංඡනවල විශ්වසනීයත්වය දැක්වීමටත් භූ දර්ශනවල සාමයටත් යොදයි."),
        q("වර්ණ සංයෝජනයකදී එක් වර්ණයක් ඉතා කුඩා ප්‍රමාණයකින් යොදා අනෙක් වර්ණවලට වඩා කැපී පෙනෙන්නට සැලැස්වීම හඳුන්වන්නේ කෙසේද?", "වර්ණ අවධාරණය (Color Accent)", "වර්ණ උදාසීනකරණය (Desaturation)", "ඒකවර්ණ සැලැස්ම (Monochrome)", "වර්ණ ක්‍රමාවරෝහණය (Gradation)", "උදාසීන අළු හෝ කළු-සුදු සිතුවමක එක් තැනක දීප්තිමත් රතු කුඩයක් තැබීම වර්ණ උද්දීපනයට උදාහරණයකි."),
        q("ඒකාකාරී සමපාත බවක් නොමැතිව ස්වාභාවික ආකර්ෂණීය වර්ණ බෙදීම සඳහා නිර්මාණ ශිල්පීන් භාවිත කරන '60-30-10 රීතිය' යනු කුමක්ද?", "ප්‍රධාන 60%, ද්විතීයික 30% හා උද්දීපන 10% යෙදීම", "සමාන ප්‍රමාණ තුනකට වර්ණ බෙදා ආලේප කිරීම", "මූලික වර්ණ හැටක් එකට මිශ්‍ර කර ගැනීම", "පසුබිමට සියයට දහයක් පමණක් වර්ණ යෙදීම", "අභ්‍යන්තර සැරසිලි, පෝස්ටර් හා සිතුවම්වල සමබර වර්ණ පාලනයට 60-30-10 අනුපාතය උපකාරී වේ."),
        q("වර්ණ දෙකක් එකට මිශ්‍ර නොකර ඉතා කුඩා ඉරි හෝ තිත් ලෙස එක ළඟ තැබීමෙන් නරඹන්නාගේ ඇස තුළදී මිශ්‍ර වීම කුමක්ද?", "දෘශ්‍ය වර්ණ මිශ්‍රණය (Optical Color Mixing)", "භෞතික තීන්ත මිශ්‍රණය", "රසායනික විරංජනය", "ප්‍රතිවිරුද්ධ අඳුර", "රතු හා කහ තිත් ඉතා ළඟින් තැබූ විට දුර සිට බලන්නාට තැඹිලි පැහැයක් සේ දිස් වීම මෙයයි."),
        q("චිත්‍රයක 'සමගාමී ප්‍රතිවිරෝධතාව' (Simultaneous Contrast) යන සංසිද්ධියෙන් සිදු වන්නේ කුමක්ද?", "යාබද වර්ණ බලපෑමෙන් මැද වර්ණය වෙනස්ව පෙනීම", "සියලු වර්ණ සම්පූර්ණයෙන් සුදු පැහැ ගැන්වීම", "වර්ණ තානය නොවෙනස්ව එකම අගයක පැවතීම", "වර්ණ චක්‍රයේ සියලු ද්විතීයික වර්ණ මැකී යාම", "අඳුරු කළු පසුබිමක අළු කොටුව ලා පැහැයෙන්ද සුදු පසුබිමක එම අළු කොටුවම තද පැහැයෙන්ද පෙනේ."),
        q("සිතුවමක 'මෘදු එළිය-අඳුර' (Low Key) හා 'දීප්තිමත් එළිය' (High Key) යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "Low Key අඳුරු තානද High Key ලා දීප්තිමත් තානද වේ", "Low Key පැතලි රේඛාද High Key වක්‍ර රේඛාද වේ", "Low Key රළු වයනයද High Key සිනිඳු වයනයද වේ", "Low Key උණුසුම් වර්ණද High Key සිසිල් වර්ණද වේ", "ගුප්ත හා ශෝකජනක බවට Low Key (උදා: රෙම්බ්‍රාන්ට්) ද ප්‍රීතිමත් සැහැල්ලු බවට High Key ද යොදා ගනී."),
        q("සිතුවමක සමස්ත හැඩයන් අතර ඇති සමබරතාව පරීක්ෂා කිරීමේදී 'දෘශ්‍ය භාරය' (Visual Weight) වැඩි වන්නේ කුමන වස්තුවකද?", "විශාල, තද අඳුරු හෝ දීප්තිමත් සංකීර්ණ වස්තුවක", "ඉතා කුඩා, ලා අළු පැහැති සරල තිතක", "හිස් සුදු පසුබිමේ ඇති පැහැදිලි විරාම කලාපයක", "සිහින් කඩඉරකින් ඇඳි සරල පසුබිම් රේඛාවක", "විශාල සැහැල්ලු වස්තුවකට වඩා කුඩා තද රතු වස්තුවකට වැඩි දෘශ්‍ය බරක් ඇති විය හැකිය."),
        q("නිර්මාණ මූලධර්ම අතර 'ක්‍රමානුකූල වෙනස්වීම' (Gradation) මගින් සිතුවමට ලැබෙන්නේ කුමක්ද?", "තානය හෝ වර්ණය පියවරෙන් මාරුවී ගැඹුර මැවීම", "අවකාශය හා රූප අතර හදිසි තියුණු කැපීම", "සෑම කොටසක්ම එකම තද වර්ණයකින් වැසී යාම", "සියලු ස්වභාවික හැඩතල ජ්‍යාමිතිකව විකෘති වීම", "අහසේ තද නිල් පැහැයේ සිට ක්ෂිතිජයේ ලා නිල් දක්වා සෙමෙන් මාරු වීම ග්‍රැඩේෂන් වේ."),
        q("සරල ජ්‍යාමිතික රටාවක් ක්‍රමානුකූලව පුනරාවර්තනය කරන 'ටෙසලේෂන්' (Tessellation) මෝස්තරයේ ප්‍රධාන ලක්ෂණය කුමක්ද?", "හිඩැස් නොතබා හැඩතල එකිනෙකට බැඳී තලය පිරවීම", "හැඩතල අහඹු ලෙස විසිරී හිස් ඉඩ තැබීම", "වෘත්ත හැඩතල පමණක් දුරින් දුරට ඇඳ තැබීම", "තනි සිරස් රේඛාවක් පමණක් නැවත නැවත ඇඳීම", "ඉස්ලාමීය ටයිල් කලාවේ හා එම්.සී. එෂර්ගේ කෘතිවල මෙම ගණිතමය රටා කලාව දක්නට ලැබේ."),
        q("සාම්ප්‍රදායික ශ්‍රී ලාංකේය මෝස්තරයක් නිර්මාණය කිරීමේදී 'ශෛලිගත කිරීම' (Stylization) යනු කුමක්ද?", "ස්වභාවික රුව සැරසිලිමය රිද්ම හැඩයකට හැරවීම", "වස්තුවේ යථාර්ථවාදී ඡායාරූප ස්වභාවය පිටපත් කිරීම", "මෝස්තරය තනි අළු පැහැයකින් පමණක් වර්ණ ගැන්වීම", "ත්‍රිමාණ සෙවණැලි යොදා ගැඹුර ඉස්මතු කර දැක්වීම", "සීන මල, ලියවැල හා හංස පූට්ටුව යනු සොබාදහමේ වස්තු ශෛලිගත කිරීමෙන් බිහි වූ මෝස්තර වේ."),
        q("චිත්‍රයක 'සංයුතිය' (Composition) යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "රාමුව තුළ මූලිකාංග සංවිධානාත්මකව සැකසීම", "වර්ණ චක්‍රයේ අනුපූරක වර්ණ පමණක් මිශ්‍ර කිරීම", "පින්සල් හා කඩදාසි වර්ග නිවැරදිව තෝරා ගැනීම", "සිතුවමේ පසුබිමට එක් සමාන්තර රේඛාවක් ගැසීම", "හොඳ සංයුතියක් නරඹන්නාගේ දෑස පහසුවෙන් ආකර්ෂණය කර ප්‍රධාන පණිවිඩය සම්ප්‍රේෂණය කරයි."),
        q("සිතුවමක නරඹන්නාගේ ඇස කැන්වසයෙන් පිටතට ලිස්සා නොයා ඇතුළත රඳවා ගැනීමට භාවිත කරන උපක්‍රමය කුමක්ද?", "මග පෙන්වන රේඛා හා කොන්වල සමබරතාව රැකීම", "ප්‍රධාන වස්තුව රාමුවේ කෙළවරින් කපා දැමීම", "සියලු මුළු හතරෙහිම එකම තද කළු පැහැය ගෑම", "පසුබිමේ වස්තූන් එකම තිරස් රේඛාවක පෙළ ගැසීම", "ඇතුළට යන මාවතක් හෝ ඇල වූ අත්තක් මගින් ඇස සිතුවමේ මධ්‍යය වෙත යළි ගෙන එනු ලැබේ."),
        q("වස්තුවක් හෝ මිනිසෙකු ඇඳීමේදී 'නිවැරදි සමානුපාතය' (Proportion) බිඳ දමා යම් අවයවයක් අතිශයින් විශාල කිරීමට කියන්නේ කුමක්ද?", "විකෘති කිරීම හෝ අතිශයෝක්තිය (Distortion)", "සමමිතික සමබරතාව (Symmetrical Balance)", "රේඛීය දෘෂ්ටිකෝණය (Linear Perspective)", "ඒකවර්ණ සංයෝජනය (Monochromatic Scale)", "කාටූන් චිත්‍රවල හිස හෝ නාසය විශාල කිරීමෙන් හාස්‍යය හෝ ප්‍රබල හැඟීම් ප්‍රකාශ කෙරේ."),
        q("ත්‍රිමාණ මූර්තියක හෝ වාස්තු නිර්මාණයක 'ආවෘත ආකෘතිය' (Closed Form) සහ 'විවෘත ආකෘතිය' (Open Form) වෙනස් වන්නේ කෙසේද?", "ආවෘත ආකෘතිය ඝන වන අතර විවෘත ආකෘතියේ හිඩැස් ඇත", "ආවෘත ආකෘතිය කඩදාසිද විවෘත ආකෘතිය ලීද වේ", "ආවෘත ආකෘතිය ද්විමානද විවෘත ආකෘතිය ත්‍රිමානද වේ", "ආවෘත ආකෘතිය වර්ණවත්ද විවෘත ආකෘතිය ඒකවර්ණද වේ", "සමාධි පිළිමය සාපේක්ෂව සංවෘත ඝන බවක් දක්වන අතර හෙන්රි මුවර්ගේ සිදුරු සහිත මූර්ති විවෘත ආකෘති වේ."),
        q("කලා නිර්මාණයේදී 'කැටි ගැසුණු රිද්මය' (Regular Rhythm) සහ 'ගලා යන රිද්මය' (Flowing Rhythm) අතර වෙනස කුමක්ද?", "සමාන පරතරය Regular වන අතර වක්‍ර චලනය Flowing වේ", "සිරස් රේඛා Regular වන අතර තිරස් රේඛා Flowing වේ", "අඳුරු වර්ණ Regular වන අතර ලා වර්ණ Flowing වේ", "සත්ව රූප Regular වන අතර ශාක රූප Flowing වේ", "වැටක කණු පෙළ ක්‍රමවත් රිද්මයක් වන අතර මහනුවර ලියවැල ගලා යන රිද්මයකට උදාහරණයකි."),
        q("මෝස්තර රටාවක් නිර්මාණය කිරීමේදී මූලික ඒකකය (Motif) කණ්ණාඩියකින් මෙන් දෙපසට හරවා පිහිටුවීම හඳුන්වන්නේ කුමන ක්‍රමය ලෙසද?", "පරාවර්තන පුනරාවර්තනය (Mirror Repeat)", "අහඹු විසිරුණු පුනරාවර්තනය (Random Repeat)", "අර්ධ පියවර පුනරාවර්තනය (Half-Drop Repeat)", "විකර්ණ ගැලපුම් රටාව (Diagonal Repeat)", "රෙදිපිළි, බතික් හා ලී කැටයම් මෝස්තරවල සමමිතික අලංකාරය ගැනීමට පරාවර්තන රටාව යොදා ගනී."),
        q("සිතුවමක පසුබිම මත තැබූ 'සිහින් දිගු හැඩතල' ඊට සමාන ප්‍රමාණයේ තනි කොටු හැඩයකට වඩා කුමන බලපෑමක් ඇති කරයිද?", "දිශානතිය හා චලන වේගය පෙන්නුම් කරයි", "සම්පූර්ණ නිශ්චල බර පමණක් දෙයි", "වර්ණ චක්‍රය නැති කරයි", "පින්සල් සේදීම අපහසු කරයි", "හැඩතලවල දිග-පළල අනුපාතය නරඹන්නාගේ ඇස ගමන් කරන දිශාව පාලනය කරයි."),
        q("බටහිර හා පෙරදිග කලාවේ සැලසුම්කරණයේදී 'විරාමය හෙවත් හුස්ම ගැනීමේ අවකාශය' (Breathing Space / White Space) වැදගත් වන්නේ ඇයි?", "අවුල් බව මුදා ප්‍රධාන තේමාව පැහැදිලි කරන බැවින්", "සමස්ත පසුබිමම සම්පූර්ණයෙන් වර්ණ ගැන්වීමට බැවින්", "කුඩා අකුරු හැකිතාක් වැඩියෙන් ඇතුළත් කළ හැකි බැවින්", "හැඩතල එක මත එක අතිපිහිටා පෙන්වීමට උදව් වන බැවින්", "පෝස්ටර්, පොත් කවර හා චීන සිතුවම්වල හිස් ඉඩ නිසා ප්‍රධාන රූපයට ප්‍රබල අගයක් ලැබේ."),
        q("වර්ණ දෙකක් අතර 'තාන ප්‍රතිවිරෝධතාව' (Value Contrast) අඩු නම් (උදා: ලා කහ මත සුදු අකුරු) කුමන ගැටලුව ඇති වේද?", "අකුරු පසුබිමෙන් වෙන්ව පැහැදිලිව නොපෙනී යාම", "සිතුවමේ මතුපිට තීන්ත ස්තරය ඉක්මනින් ඉරිතළා යාම", "අනුපූරක වර්ණ එකිනෙකට ගැටී තද කළු පැහැය මතු වීම", "සංයුතියේ සමමිතික සමබරතාව සම්පූර්ණයෙන් බිඳ වැටීම", "පෝස්ටරයක අකුරු හා පසුබිම අතර පැහැදිලි ආලෝක-අඳුරු වෙනසක් තිබීම කියවීමේ පහසුවට අත්‍යවශ්‍ය වේ."),
        q("වර්ණ සංයෝජනයේදී 'තැඹිලි' වර්ණය පැවතීම නිසා සිතුවමට ලැබෙන චිත්තවේගීය ගුණය කුමක්ද?", "උණුසුම, ප්‍රබෝධය, ශක්තිය හා ජවසම්පන්න බව", "සීතල හිම කඳු හා ගැඹුරු සාගරයේ නිශ්චල බව", "තද අඳුරු ගුප්ත ස්වභාවය හා නිහඬ ශෝකජනක බව", "සිසිල් සෙවණ හා සම්පූර්ණ හුදෙකලා මානසික සුවය", "රතු හා කහ එක්ව සෑදෙන තැඹිලි වර්ණය සූර්යාලෝකය හා උද්යෝගය නිරූපණය කරයි."),
        q("කඩදාසියක සිතුවමක් ඇඳීමට පෙර සංයුති කිහිපයක් අත්හදා බැලීමට කුඩා කොටු තුළ අඳින ඉක්මන් කෙටුම්පත් මොනවාද?", "තම්බ්නේල් සටහන් (Thumbnail Sketches)", "අවසන් මාස්ටර්පීස් චිත්‍රය", "ලිනෝ මුද්‍රණය", "ටෙම්පරා බදාමය", "විශාල කැන්වසය මත ඇඳීමට පෙර සංයුතියේ සමබරතාව පරීක්ෂා කිරීමට කුඩා කෙටුම්පත් සැකසීම සාර්ථක ක්‍රමයකි."),
        q("චිත්‍රයක ප්‍රධාන වස්තුව වටා අවධානය යොමු කිරීමට පසුබිමේ ගස් අතු හෝ දොර උළුවස්සක් මෙන් ඇඳීමේ සංයුති උපක්‍රමය කුමක්ද?", "සංයුති රාමුගත කිරීම (Framing)", "අන්ධ සමෝච්ඡ රේඛා (Blind Contour)", "දෘශ්‍ය වර්ණ මිශ්‍රණය (Optical Mix)", "ටෙසලේෂන් රටා (Tessellation)", "පෙරබිමේ ස්වභාවික අංගවලින් දර්ශනය වට කිරීමෙන් නරඹන්නාගේ ඇස කෙළින්ම නාභිගත තැනට යොමු වේ."),
        q("වර්ණ මිශ්‍ර කිරීමේදී 'වර්ණ උෂ්ණත්වය' (Color Temperature) යන සංකල්පය අනුව 'වතුර වැනි පසුබිමක්' ඉදිරියට නොපැන පසුපසට යැවීමට ගත යුත්තේ කුමක්ද?", "නිල්, දම් හෝ සිසිල් අළු මිශ්‍ර තානයන්", "තද රතු-තැඹිලි හා දීප්තිමත් උණුසුම් වර්ණ", "සුදු මිශ්‍ර කහ හා රන්වන් වර්ණ තානයන්", "පිරිසිදු සිඳුරු රතු හා රෝස වර්ණ තානයන්", "සිසිල් වර්ණ ආලෝක තරංග ස්වභාවය නිසා ඈතට ගමන් කරන හැඟීමක් ලබා දෙයි."),
        q("සාම්ප්‍රදායික චිත්‍ර කලාවේ පමණක් නොව නූතන කලාවේද 'තානය' (Tone) නොමැතිව රේඛාවෙන් පමණක් වස්තුවක බර දැක්විය හැක්කේ කෙසේද?", "පහළ දාරයේ රේඛාවේ ඝනකම හා තද බව වැඩි කිරීමෙන්", "සියලු රේඛා එකම සිහින් මට්ටමින් සමානව ඇඳීමෙන්", "වස්තුවේ ඉහළ දාරය කඩඉරි ලෙස සැහැල්ලුවෙන් ඇඳීමෙන්", "පසුබිම පුරා සමාන්තර තිරස් රේඛා කිහිපයක් ගැසීමෙන්", "වස්තුව බිම ස්පර්ශ වන යටි දාරයේ රේඛාව තදින් හා මහතින් ඇඳීමෙන් බර දැනේ."),
        q("වස්තූන් කිහිපයක් චිත්‍රයක තබන විට 'ඔත්තේ සංඛ්‍යාවක්' (Rule of Odds - 3, 5 වැනි) තැබීම වඩා ආකර්ෂණීය වන්නේ ඇයි?", "යුගල නොවී ස්වභාවික අසමමිතික රිද්මයක් මැවෙන බැවින්", "සෑම විටම පරිපූර්ණ දර්පණ සමමිතියක් ඇති වන බැවින්", "පසුබිමේ වර්ණ ප්‍රතිවිරෝධතාව සම්පූර්ණයෙන් අඩු වන බැවින්", "සංයුතිය තුළ කිසිදු නාභිගත ලක්ෂ්‍යයක් නොපවතින බැවින්", "නිශ්චල ජීව චිත්‍රයක (Still Life) පලතුරු හෝ බඳුන් 3ක් හෝ 5ක් තැබීමෙන් ඇස වඩාත් උනන්දුවෙන් චලනය වේ."),
        q("වර්ණ චක්‍රයේ එකම වර්ණයේ උණුසුම් සහ සිසිල් ප්‍රභේද පවතීද? උදාහරණයක් ලෙස 'උණුසුම් රතු' සහ 'සිසිල් රතු' වෙන් වන්නේ කෙසේද?", "තැඹිලි බර රතු උණුසුම් වන අතර දම් බර රතු සිසිල් වේ", "රතු වර්ණයට සිසිල් හෝ උණුසුම් ලෙස ප්‍රභේද නොපවතී", "කළු මිශ්‍ර කළ රතු උණුසුම් වන අතර සුදු මිශ්‍ර රතු සිසිල් වේ", "පැතලි රතු සිසිල් වන අතර දිලිසෙන රතු උණුසුම් වේ", "තනි මූලික වර්ණයක පවා යාබද වර්ණ අනුව උණුසුම්-සිසිල් නැඹුරුවක් (Color Bias) තිබීම වර්ණ මිශ්‍රණයේදී වැදගත්ය."),
        q("මෝස්තර නිර්මාණයකදී 'තද රටාවක් සහිත කොටසක්' සහ 'හිස් පැහැදිලි කොටසක්' එක්ව යොදන්නේ කුමන මූලධර්මය රැකීමටද?", "ප්‍රතිවිරෝධතාව හා ඇසට විවේකයක් ලබා දීමට", "සම්පූර්ණ සමමිතික සමබරතාව පමණක් ආරක්ෂා කිරීමට", "අනුපූරක වර්ණ සංයෝජනයේ උෂ්ණත්වය අඩු කිරීමට", "රටාවේ සියලු ජ්‍යාමිතික හැඩතල විකෘති කිරීමට", "සෑම තැනම කැටයම් පිරවීම වෙනුවට හිස් කලාප තැබීමෙන් රටාවේ අගය දෙගුණ වේ."),
        q("චිත්‍ර කලාවේදී 'අමුර්ත හෙවත් වියුක්ත හැඩතල' (Abstract Shapes) බිහි වන්නේ කුමන ක්‍රියාවලියකින්ද?", "ස්වභාවික රූප සරල කර හෝ ජ්‍යාමිතිකව ඌනනය කිරීමෙන්", "වස්තුවේ පෙනුම ඡායාරූපයක් මෙන් යථාර්ථවාදීව පිටපත් කිරීමෙන්", "ඒකලක්ෂ්‍ය දෘෂ්ටිකෝණ රීතියට අනුව ගොඩනැගිලි මැන ඇඳීමෙන්", "සියලු මෝස්තර දර්පණ සමමිතියෙන් නැවත නැවත පුනරාවර්තනය කිරීමෙන්", "පිකාසෝගේ ගොනා සරල කර ඇඳි මාලාව ස්වභාවික රූපයකින් වියුක්ත ආකෘතියක් සෑදෙන හැටි පෙන්වයි."),
        q("නිර්මාණයක 'ඒකාබද්ධතාව' (Unity) සැකසීමේදී පහත සඳහන් ක්‍රමවලින් වඩාත් ඵලදායී ක්‍රමය කුමක්ද?", "එකම වර්ණ පවුලක් හා සමාන හැඩතල පුනරාවර්තනය කිරීම", "සෑම කොටසක්ම එකිනෙකට වෙනස් විරුද්ධ ශෛලිවලින් ඇඳීම", "වස්තු එකිනෙකින් ඉතා ඈතින් හතර කොනේ විසුරුවා තැබීම", "හැඩතල හා වර්ණ අතර කිසිදු සම්බන්ධයක් නොතැබීම", "සමාන මූලිකාංග අතර දෘශ්‍ය සබඳතාව ගොඩනැගීමෙන් නිර්මාණය එකම පවුලක් සේ පෙනේ."),
        q("ශ්‍රී ලංකාවේ අ.පො.ස. සාමාන්‍ය පෙළ චිත්‍ර කලා විෂය නිර්දේශයේ මූලිකාංග හා මූලධර්ම ඉගැන්වීමේ ප්‍රධාන අරමුණ කුමක්ද?", "සෞන්දර්ය රසවින්දනය හා නිර්මාණශීලී සංවිධානය ප්‍රගුණ කිරීම", "ජ්‍යාමිතික මිනුම් හා ගණිත සූත්‍ර පමණක් කටපාඩම් කිරීම", "කෘත්‍රිම ඡායාරූප කිසිදු වෙනසකින් තොරව පිටපත් කිරීම", "පෞරාණික කැටයම් මෝස්තර වෙනස් නොකර අනුකරණය කිරීම", "මූලික රීති අවබෝධ කර ගත් විට පෝස්ටර්, රූප සංයුති හා කලා විචාරය නිවැරදිව කළ හැකිය.")
    )
}
